const fs = require('fs');
const path = require('path');

const dataDir = path.join(process.cwd(), 'data');
if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir);
}

function ensureFile(modelName) {
  const file = path.join(dataDir, `${modelName}.json`);
  if (!fs.existsSync(file)) {
    fs.writeFileSync(file, '[]', 'utf8');
  }
  return file;
}

function readData(modelName) {
  const file = ensureFile(modelName);
  const raw = fs.readFileSync(file, 'utf8');
  try {
    return JSON.parse(raw);
  } catch (err) {
    return [];
  }
}

function writeData(modelName, data) {
  const file = ensureFile(modelName);
  fs.writeFileSync(file, JSON.stringify(data, null, 2));
}

function generateId() {
  return Math.random().toString(16).slice(2) + Math.random().toString(16).slice(2);
}

class Schema {
  constructor(definition, options = {}) {
    this.definition = definition;
    this.options = options;
  }
}

const models = {};

function connect() {
  return Promise.resolve({ connection: { readyState: 1 } });
}

function model(name, schema) {
  if (models[name]) return models[name];
  class Model {
    constructor(doc = {}) {
      Object.assign(this, doc);
      if (!this._id) {
        this._id = generateId();
      }
    }

    save() {
      const items = readData(name);
      const existingIndex = items.findIndex((item) => item._id === this._id);
      const plain = { ...this };
      if (existingIndex >= 0) {
        items[existingIndex] = plain;
      } else {
        items.push(plain);
      }
      writeData(name, items);
      return Promise.resolve(this);
    }

    toObject() {
      return { ...this };
    }

    static find(query = {}) {
      const items = readData(name);
      return Promise.resolve(items.filter((item) => matchQuery(item, query)).map((item) => new Model(item)));
    }

    static findOne(query = {}) {
      return Model.find(query).then((results) => results[0] || null);
    }

    static findById(id) {
      const items = readData(name);
      const found = items.find((item) => item._id === id);
      return Promise.resolve(found ? new Model(found) : null);
    }

    static findByIdAndUpdate(id, update, options = {}) {
      const items = readData(name);
      const idx = items.findIndex((item) => item._id === id);
      if (idx === -1) return Promise.resolve(null);
      const updated = { ...items[idx], ...flattenUpdate(update) };
      items[idx] = updated;
      writeData(name, items);
      return Promise.resolve(options.new ? new Model(updated) : new Model(items[idx]));
    }

    static findByIdAndDelete(id) {
      const items = readData(name);
      const idx = items.findIndex((item) => item._id === id);
      if (idx === -1) return Promise.resolve(null);
      const [removed] = items.splice(idx, 1);
      writeData(name, items);
      return Promise.resolve(new Model(removed));
    }

    static deleteMany(query = {}) {
      const items = readData(name);
      const remaining = items.filter((item) => !matchQuery(item, query));
      writeData(name, remaining);
      return Promise.resolve();
    }

    static create(doc) {
      const instance = new Model(doc);
      return instance.save();
    }

    static countDocuments(query = {}) {
      const items = readData(name);
      return Promise.resolve(items.filter((item) => matchQuery(item, query)).length);
    }

    static aggregate(pipeline = []) {
      let data = readData(name);
      pipeline.forEach((stage) => {
        if (stage.$match) {
          data = data.filter((item) => matchQuery(item, stage.$match));
        }
        if (stage.$group) {
          const { _id, ...accumulators } = stage.$group;
          const groups = new Map();
          data.forEach((item) => {
            const key = typeof _id === 'function' ? _id(item) : item[_id];
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push(item);
          });
          data = Array.from(groups.entries()).map(([key, items]) => {
            const result = { _id: key };
            Object.keys(accumulators).forEach((field) => {
              const acc = accumulators[field];
              if (acc.$sum !== undefined) {
                const sumField = acc.$sum;
                if (typeof sumField === 'number') {
                  result[field] = items.length * sumField;
                } else {
                  result[field] = items.reduce((accSum, item) => accSum + (Number(item[sumField]) || 0), 0);
                }
              }
              if (acc.$count !== undefined) {
                result[field] = items.length;
              }
            });
            return result;
          });
        }
      });
      return Promise.resolve(data);
    }
  }

  models[name] = Model;
  Model.schema = schema;
  return Model;
}

function matchQuery(item, query) {
  return Object.keys(query).every((key) => {
    if (typeof query[key] === 'object' && query[key] !== null) {
      if ('$in' in query[key]) {
        return query[key].$in.includes(item[key]);
      }
      if ('$ne' in query[key]) {
        return item[key] !== query[key].$ne;
      }
    }
    return item[key] === query[key];
  });
}

function flattenUpdate(update) {
  if (!update) return {};
  if (update.$set) {
    return update.$set;
  }
  return update;
}

module.exports = { connect, Schema, model, Types: { ObjectId: { generate: generateId } } };
